// Platform-wide economic parameters contract (BLOCKCHAIN_ECONOMICS §4–§8, §12).
//
// Editable in place, address stable: `update_params` is admin-gated and MUTATES
// STORAGE (no redeploy), so every other contract / off-chain node can hard-pin
// this address. Each update is bounds-validated on-chain (mirroring the §12
// invariants), emits a `ParamsUpdated` log, and rejects unauthorized senders.
// The admin is a single configurable address today, designed to later point at a
// multisig (rotate via `update_admin`).

import "common"
import "global_params_types"

contract GlobalParams {
    storage: GlobalParamsStorage
    incomingMessages: AllowedMessageToGlobalParams
}

type AllowedMessageToGlobalParams =
    | UpdateParams
    | UpdateAdmin
    | SetBlocklisted

fun onBouncedMessage(_in: InMessageBounced) {}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToGlobalParams.fromSlice(in.body);

    match (msg) {
        // Admin-gated, in-place parameter update. Address is unchanged because we
        // setData (mutate) rather than redeploy.
        UpdateParams => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ERROR_NOT_ADMIN;

            // Bounds-validate on-chain BEFORE persisting (reject bad updates).
            val newParams = msg.params.load();
            validateEcoParams(newParams);

            storage.feeRecipient = msg.feeRecipient;
            storage.params = msg.params;
            storage.save();

            // Emit a "params updated" event for off-chain indexers.
            val ev = createExternalLogMessage({
                dest: ExtOutLogBucket { topic: EVENT_PARAMS_UPDATED },
                body: ParamsUpdated {
                    queryId: msg.queryId,
                    platformFeeBps: newParams.platformFeeBps,
                    minStake: newParams.minStake,
                },
            });
            ev.send(SEND_MODE_REGULAR);
        }

        // Admin rotation (single key -> multisig handoff). Admin-gated.
        UpdateAdmin => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ERROR_NOT_ADMIN;
            storage.admin = msg.newAdmin;
            storage.save();
        }

        // Governance blocklist update (anti-abuse). Admin-gated, mutates storage
        // in place. Sets the subject blocked (1) or clears it (0).
        SetBlocklisted => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ERROR_NOT_ADMIN;
            storage.blocklist.set(msg.subject, (msg.blocked ? 1 : 0) as uint1);
            storage.save();
        }

        else => {
            assert (in.body.isEmpty()) throw ERROR_INVALID_OP;
        }
    }
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

get fun get_params(): GlobalParamsView {
    val storage = lazy GlobalParamsStorage.load();
    return {
        admin: storage.admin,
        feeRecipient: storage.feeRecipient,
        params: storage.params,
    };
}

get fun get_admin(): address {
    val storage = lazy GlobalParamsStorage.load();
    return storage.admin;
}

get fun get_fee_recipient(): address {
    val storage = lazy GlobalParamsStorage.load();
    return storage.feeRecipient;
}

// Whether a subject (256-bit account hash) is on the governance blocklist.
get fun get_blocklisted(subject: int): bool {
    val storage = lazy GlobalParamsStorage.load();
    val found = storage.blocklist.get(subject as uint256);
    if (!found.isFound) {
        return false;
    }
    return found.loadValue() == 1;
}

// Shared error codes, opcodes and constants for the duckdb-p2p settlement layer.
//
// These contracts implement the *paid* path of the economic layer described in
// `docs/BLOCKCHAIN_ECONOMICS.md`. Free jobs never touch any of this code — the
// requester runs them through the off-chain coordinator with the `NoopSettlement`
// path and there is zero on-chain interaction (see §8.2 "Free vs paid path").
//
// Design constraints honoured here (BLOCKCHAIN_ECONOMICS §1, §8):
//   * sharded per-node state (no global contract): one StakeVault per node,
//     one JobEscrow per job — never a single hot contract.
//   * non-custodial: release is governed entirely by contract code (quorum
//     result-hash, challenge window, unbonding cooldown), never a platform key.
//   * defensive TON style: explicit gas floors, bounce-safe, carry-value.
// ---------------------------------------------------------------------------
// Error codes (numeric, cheap to assert against in tests)
// ---------------------------------------------------------------------------

const ERROR_NOT_OWNER = 132 // sender is not the contract owner
const ERROR_NOT_FROM_MASTER = 133 // sender is not the jetton master (vault)
const ERROR_NOT_VALID_WALLET = 134 // sender is not a legitimate sibling receipt wallet
const ERROR_UNAUTHORIZED_BURN = 135 // burn notification not from the owner's wallet
const ERROR_BALANCE_NEGATIVE = 136 // resulting balance would be negative
const ERROR_NOT_ENOUGH_GAS = 137 // attached value too small to cover the operation
const ERROR_RECEIPT_LOCKED = 138 // stake-receipt jetton is non-transferable (anti-exit)
const ERROR_WRONG_WORKCHAIN = 333 // address is not in the basechain
const ERROR_INVALID_OP = 0xffff // unknown opcode

// Stake vault
const ERROR_NOT_SLASHER = 200 // sender is not the authorized slasher (dispute contract)
const ERROR_NOTHING_TO_UNBOND = 201 // unbond requested but no eligible stake
const ERROR_UNBOND_IN_PROGRESS = 202 // a prior unbond is still cooling down
const ERROR_COOLDOWN_NOT_ELAPSED = 203 // withdraw before the unbonding cooldown finished
const ERROR_NO_UNBONDING = 204 // withdraw with nothing in the unbonding bucket
const ERROR_KEEPER_TOO_EARLY = 205 // keeper withdraw before the owner-grace window
const ERROR_SLASH_EXCEEDS_STAKE = 206 // slash amount larger than slashable stake
const ERROR_INVALID_SPLIT = 207 // slash split bps do not sum to 10000

// Escrow
const ERROR_ESCROW_NOT_FUNDED = 220 // escrow opened without the requester's max-bid B
const ERROR_NOT_REQUESTER = 221 // settle/refund by someone other than the requester
const ERROR_NOT_ARBITER = 222 // settle by someone other than the bound arbiter
const ERROR_HASH_MISMATCH = 223 // provided result hash != the committed quorum hash
const ERROR_ALREADY_SETTLED = 224 // escrow already released
const ERROR_TIMEOUT_NOT_REACHED = 225 // refund-on-timeout before the deadline
const ERROR_PAYOUT_EXCEEDS_ESCROW = 226 // requested payout exceeds the locked escrow B

// Global params (platform-wide config)
const ERROR_NOT_ADMIN = 260 // sender is not the configured admin (or multisig)
const ERROR_PARAMS_OUT_OF_BOUNDS = 261 // proposed params violate a §12 invariant

// Record anchor / dispute
const ERROR_BAD_PREV_ROOT = 240 // submitted root does not chain to the stored prev_root
const ERROR_EPOCH_REGRESSION = 241 // epoch did not advance monotonically
const ERROR_INSUFFICIENT_ANCHOR_STAKE = 242 // keeper stake-weight below the acceptance threshold
const ERROR_BAD_INCLUSION_PROOF = 243 // Merkle inclusion proof does not reproduce the root
const ERROR_DISPUTE_BOND_TOO_LOW = 244 // challenger bond below the configured minimum
const ERROR_NO_SUCH_DISPUTE = 245 // verdict for an unknown dispute id
const ERROR_NOT_VERDICT_AUTHORITY = 246 // verdict from a non-authoritative source

// ---------------------------------------------------------------------------
// Opcodes — keep TEP-74 standard values verbatim for ecosystem interop.
// ---------------------------------------------------------------------------

// TEP-74 jetton standard
const OP_JETTON_TRANSFER = 0x0f8a7ea5
const OP_JETTON_TRANSFER_INTERNAL = 0x178d4519
const OP_JETTON_NOTIFICATION = 0x7362d09c
const OP_JETTON_EXCESSES = 0xd53276db
const OP_JETTON_BURN = 0x595f07bc
const OP_JETTON_BURN_NOTIFICATION = 0x7bdd97de
const OP_PROVIDE_WALLET_ADDRESS = 0x2c76b973
const OP_TAKE_WALLET_ADDRESS = 0xd1735400

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MIN_TONS_FOR_STORAGE = ton("0.05")
const BPS_DENOM = 10000 // basis-points denominator for splits/fractions

// Status bit flags for the stake-receipt wallet.
const RECEIPT_STATUS_LOCKED = 1 // bit 0: outgoing transfers locked (default)

fun assertBasechain(addr: address) {
    assert (addr.getWorkchain() == BASECHAIN) throw ERROR_WRONG_WORKCHAIN;
}

// Storage, messages and on-chain bounds validation for the platform-wide
// `GlobalParams` contract (BLOCKCHAIN_ECONOMICS §4–§8, §12).
//
// This is the ONE ecosystem-wide contract: it holds the economic parameters
// every other contract / off-chain node reads (fees, surcharge, participation
// commission, slash %s + split, min-stake tiers, stake cap, unbonding /
// challenge windows, default selection N/quorum/checksum, ranking weights, fee
// recipient). It is **editable in place**: an admin-gated `update_params`
// MUTATES STORAGE — there is no redeploy — so the contract **address is stable**
// and other contracts can hard-reference it. The admin is a single configurable
// address today but is designed to later point at a multisig (admin rotation via
// `update_admin`).
//
// Every update is **bounds-validated on-chain**, mirroring the §12 cross-field
// invariants enforced off-chain in `crates/config` (so the chain is the source
// of truth and cannot be driven into an inconsistent state even by the admin).

import "common"

const OP_UPDATE_PARAMS = 0x47504101 // "GPA" 01
const OP_UPDATE_ADMIN = 0x47504102  // "GPA" 02
const OP_SET_BLOCKLISTED = 0x47504103 // "GPA" 03 — governance blocklist (anti-abuse)

// Log topic for the emitted "params updated" event (external-out message), so
// off-chain indexers can watch parameter changes without parsing internals.
const EVENT_PARAMS_UPDATED = 0x6770_7570 // "gpup"

// Bulk economic parameters, kept in a child cell (bit budget). All fractions are
// basis points (bps, /10000); stakes are coins; windows are seconds; selection
// counts are small ints; ranking weights are bps.
struct EcoParams {
    platformFeeBps: uint16
    surchargeBps: uint16
    participationCommissionBps: uint16   // κ — must be small (<= 1000 bps = 10%)
    slashWrongBps: uint16
    slashCheatBps: uint16
    slashDowntimeBps: uint16
    slashEquivocationBps: uint16
    splitChallengerBps: uint16
    splitRedundancyBps: uint16
    splitBurnBps: uint16
    splitTreasuryBps: uint16
    minStake: coins
    minStakeInternal: coins
    minStakeSensitive: coins
    stakeCap: coins
    unbondingSecs: uint32
    challengeWindowSecs: uint32
    nPublic: uint8
    nDefault: uint8
    nMax: uint8
    quorum: uint8
    checksumMin: uint8
    wQualityBps: uint16
    wStakeBps: uint16
    wPriceBps: uint16
}

struct GlobalParamsStorage {
    admin: address          // gate for update_params / update_admin (→ multisig later)
    feeRecipient: address   // platform fee destination (configurable, §8.2)
    params: Cell<EcoParams> // the bulk params child cell
    // Governance blocklist (ARCHITECTURE "Abuse resistance"): admin-gated, for
    // egregious PROVABLE cases. Keyed by the subject's 256-bit account hash;
    // value 1 = blocked. Nodes may optionally consult this on-chain list, but
    // each still decides independently (it is an additional source, not a
    // central authority that forces refusal).
    blocklist: map<uint256, uint1>
}

fun GlobalParamsStorage.load(): GlobalParamsStorage {
    return GlobalParamsStorage.fromCell(contract.getData());
}

fun GlobalParamsStorage.save(self) {
    contract.setData(self.toCell());
}

// Admin-gated parameter update. Mutates storage in place (no redeploy → address
// unchanged). `feeRecipient` and the full `params` cell are replaced atomically.
struct (0x47504101) UpdateParams {
    queryId: uint64
    feeRecipient: address
    params: Cell<EcoParams>
}

// Admin rotation (e.g. hand off to a multisig once one is deployed).
struct (0x47504102) UpdateAdmin {
    queryId: uint64
    newAdmin: address
}

// Admin-gated governance blocklist update (anti-abuse). `subject` is the 256-bit
// account hash of the actor; `blocked = true` adds it, `false` clears it.
struct (0x47504103) SetBlocklisted {
    queryId: uint64
    subject: uint256
    blocked: bool
}

// Emitted as an external-out log on every successful update.
struct ParamsUpdated {
    queryId: uint64
    platformFeeBps: uint16
    minStake: coins
}

// Getter shape returned by `get_params`.
struct GlobalParamsView {
    admin: address
    feeRecipient: address
    params: Cell<EcoParams>
}

// On-chain bounds validation, mirroring the §12 cross-field invariants enforced
// off-chain by `EconomicsConfig::validate`. Throws ERROR_PARAMS_OUT_OF_BOUNDS on
// any violation so a bad admin update is rejected and storage stays consistent.
fun validateEcoParams(p: EcoParams) {
    // All bps fractions within [0, 10000].
    assert (p.platformFeeBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.surchargeBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.slashWrongBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.slashCheatBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.slashDowntimeBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.slashEquivocationBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.wQualityBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.wStakeBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.wPriceBps <= BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;

    // κ (participation commission) must be small: <= 10% (§4.2).
    assert (p.participationCommissionBps <= 1000) throw ERROR_PARAMS_OUT_OF_BOUNDS;

    // Slash split must sum to exactly 100%.
    val splitSum = p.splitChallengerBps + p.splitRedundancyBps + p.splitBurnBps + p.splitTreasuryBps;
    assert (splitSum == BPS_DENOM) throw ERROR_PARAMS_OUT_OF_BOUNDS;

    // Per-class min-stake monotonicity + cap >= min.
    assert (p.minStakeSensitive >= p.minStakeInternal) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.minStakeInternal >= p.minStake) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.stakeCap >= p.minStake) throw ERROR_PARAMS_OUT_OF_BOUNDS;

    // Unbonding must outlast the challenge window (§8.4).
    assert (p.unbondingSecs >= p.challengeWindowSecs) throw ERROR_PARAMS_OUT_OF_BOUNDS;

    // Selection ordering: n_max >= n_default >= n_public >= checksum_min >= 1, and
    // a sane quorum (1 <= quorum <= n_default).
    assert (p.checksumMin >= 1) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.nPublic >= p.checksumMin) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.nDefault >= p.nPublic) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.nMax >= p.nDefault) throw ERROR_PARAMS_OUT_OF_BOUNDS;
    assert (p.quorum >= 1 && p.quorum <= p.nDefault) throw ERROR_PARAMS_OUT_OF_BOUNDS;
}
